import 'package:flutter/material.dart';
import '../core/app_state.dart';
import '../models/models.dart';

class AssistantScreen extends StatefulWidget { final AppState state; const AssistantScreen({super.key, required this.state}); @override State<AssistantScreen> createState() => _AssistantScreenState(); }
class _AssistantScreenState extends State<AssistantScreen> { final input = TextEditingController(); final messages = <ChatMessage>[const ChatMessage('Hi, I’m here with you. I can help plan a safer route, prepare a check-in, or talk through what’s happening.')]; void send() { if (input.text.trim().isEmpty) return; final text = input.text.trim(); setState(() { messages.add(ChatMessage(text, fromUser: true)); messages.add(const ChatMessage('I hear you. You can start a journey or open SOS from the home screen. If you feel in immediate danger, contact local emergency services.')); input.clear(); }); } @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('SafeHer assistant')), body: Column(children: [Expanded(child: ListView.builder(padding: const EdgeInsets.all(20), itemCount: messages.length, itemBuilder: (_, i) { final m = messages[i]; return Align(alignment: m.fromUser ? Alignment.centerRight : Alignment.centerLeft, child: Container(margin: const EdgeInsets.only(bottom: 12), padding: const EdgeInsets.all(14), constraints: const BoxConstraints(maxWidth: 320), decoration: BoxDecoration(color: m.fromUser ? Theme.of(context).colorScheme.primaryContainer : Colors.white, borderRadius: BorderRadius.circular(18)), child: Text(m.text))); })), Padding(padding: const EdgeInsets.all(12), child: Row(children: [Expanded(child: TextField(controller: input, onSubmitted: (_) => send(), decoration: const InputDecoration(hintText: 'How can I help?'))), IconButton.filled(onPressed: send, icon: const Icon(Icons.arrow_upward))]))])); }
